package com.hyperathlete.app.domain.program

import com.hyperathlete.app.domain.model.AppLanguage
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/*
 * The training program seed (brief §14–15), stored as assets/program/program.json and generated by
 * tools/gen_program.py. Everything the app shows about a session comes from here.
 */

/** Text in three flavours: Arabic, English, and the mixed mode (Arabic with English terms). */
@Serializable
data class Txt(val ar: String, val en: String, val mx: String? = null) {
    /** Interface text (notes, muscles): English only in the English mode. */
    fun ui(language: AppLanguage): String = when (language) {
        AppLanguage.ENGLISH -> en
        AppLanguage.MIXED -> mx ?: ar
        AppLanguage.ARABIC -> ar
    }

    /** Exercise names: English unless the user picked full Arabic. */
    fun term(language: AppLanguage): String = if (language == AppLanguage.ARABIC) ar else en
}

@Serializable
enum class Measure { REPS, TIME, DISTANCE, LENGTH }

@Serializable
enum class Load { WEIGHTED, BODYWEIGHT, NONE }

/** Brief §15.1: compound lifts stop 1–2 reps short of failure, isolation takes the last set to failure. */
@Serializable
enum class LiftClass { COMPOUND, ISOLATION, OTHER }

/** Equipment, which also sets the weight jump for double progression (brief §15.2). */
@Serializable
enum class Gear(val stepKg: Double) {
    BARBELL(2.5), DUMBBELL(2.0), CABLE(2.5), MACHINE(2.5), PLATE(2.5), KETTLEBELL(4.0),
    SLED(10.0), SANDBAG(5.0), MEDBALL(1.0), BELT(2.5), BODY(0.0),
}

@Serializable
data class Exercise(
    val id: String,
    val name: Txt,
    val muscles: Txt,
    val cls: LiftClass = LiftClass.OTHER,
    val measure: Measure = Measure.REPS,
    val load: Load = Load.NONE,
    val gear: Gear = Gear.BODY,
    val art: String,
    val perSide: Boolean = false,
    /** Loads the knee (legs, jumps, sled): asks for knee pain afterwards (brief §10.7). */
    val knee: Boolean = false,
    /** Lower-body lift: 3-second lowering during the foundation phase (brief §15.4). */
    val lower: Boolean = false,
    val cue: Txt? = null,
)

@Serializable
data class Slot(
    @SerialName("ex") val exercise: String,
    val sets: Int = 1,
    val min: Int,
    val max: Int = min,
    /** [min, max] seconds; straight blocks only (superset / circuit rest is the block's). */
    val rest: List<Int>? = null,
    val note: Txt? = null,
    val alts: List<String> = emptyList(),
    /** [from, to] weeks of the 9-week cycle this slot applies to; null = always. */
    val weeks: List<Int>? = null,
    /** Overrides the exercise's load for these weeks (e.g. back extensions without a plate). */
    val load: Load? = null,
) {
    fun appliesTo(week: Int): Boolean = weeks == null || week in weeks[0]..weeks[1]
}

@Serializable
enum class BlockType { STRAIGHT, SUPERSET, CIRCUIT }

@Serializable
data class Block(
    val id: String,
    val type: BlockType = BlockType.STRAIGHT,
    val rounds: Int = 1,
    val rest: List<Int>,
    val slots: List<Slot>,
    val title: Txt? = null,
    val minutes: Int? = null,
    val note: Txt? = null,
)

@Serializable
data class ProgramDay(
    val day: String,
    val blocks: List<Block>,
    val notes: List<Txt> = emptyList(),
)

@Serializable
data class Program(
    val version: Int,
    val exercises: List<Exercise>,
    val days: List<ProgramDay>,
) {
    fun exercise(id: String): Exercise = exerciseOrNull(id) ?: error("Unknown exercise $id")
    fun exerciseOrNull(id: String): Exercise? = exercises.firstOrNull { it.id == id }
    fun day(day: java.time.DayOfWeek): ProgramDay = days.first { it.day == day.name }

    companion object {
        val json = Json { ignoreUnknownKeys = true; explicitNulls = false }
        fun parse(text: String): Program = json.decodeFromString(serializer(), text)
    }
}
